 [("Get-WinEvent -FilterHashtable @{LogName='System'; Id=7000} -MaxEvents 2",0,"The AppRelay service failed to start (timeout at boot)",""),
  ("(Get-CimInstance Win32_Service -Filter \"Name='AppRelay'\").StartMode",0,"Auto","")],
